def galaxy():
    seed=[0x5a4a,0x0248,0xb753]; pairs='..LEXEGEZACEBISOUSESARMAINDIREA.ERATENBERALAVETIEDORQUANTEISRION'; out=[]
    for i in range(256):
        x,y=seed[1]>>8,seed[0]>>8; name=''; long=seed[0]&64
        for k in range(4):
            j=2*((seed[2]>>8)&31)
            if k<3 or long: name+=''.join(c for c in pairs[j:j+2] if c not in '. ')
            seed=[seed[1],seed[2],sum(seed)&65535]
        out.append(dict(system=i,name=name,x=x,y=y,region=(x//64)+4*(y//64)))
    return out

def main():
    systems=galaxy(); rng=random.Random(4661984)
    # Every system gets slot 2; exactly half receive slot 3. Quotas are explicit.
    sites=[(s,2) for s in systems]+[(s,3) for s in systems if ((s['system']*73+19)&255)<128]
    rng.shuffle(sites); remaining={i+4:(20 if d[7]==0 else 13 if d[7]==1 else 5) for i,d in enumerate(NEW)}
    assigned=[]; table=[[0,0] for _ in systems]; regions=collections.Counter()
    for s,slot in sites:
        def cost(t):
            local=sum(math.exp(-(((s['x']-o['x'])**2+((s['y']-o['y'])*.5)**2)/1000)) for o,k in assigned if k==t)
            return regions[s['region'],t]*3+local*5 + (20-remaining[t])*.018 + rng.random()*.03 + (10000 if t in table[s['system']] else 0)
        choices=[t for t,n in remaining.items() if n]
        t=min(choices,key=cost);table[s['system']][slot-2]=t;remaining[t]-=1;assigned.append((s,t));regions[s['region'],t]+=1
    for s,row in enumerate(table):
        if row[0]==row[1]:
            other=next(j for j,r in enumerate(table) if j!=s and row[0] not in r and r[0]!=row[1])
            table[s][1],table[other][0]=table[other][0],table[s][1]
    assert not any(remaining.values())
    assert all(a!=b for a,b in table)
    assert len(NEW)==28 and sum(t>0 for row in table for t in row)==384
    header=['/* Generated by tools/generate-natural-anomalies.py; fixed spatially balanced assignments. */',
            '#ifndef NATURAL_ANOMALY_DATA_H','#define NATURAL_ANOMALY_DATA_H','#define RIFT_TYPE_COUNT 32',
            'static const unsigned char natural_anomaly_sites[256][2]={']
    header += [f' {{{a},{b}}}, /* {s["system"]:03d} {s["name"]} */' for s,(a,b) in zip(systems,table)]
    header += ['};','#endif','']
    (ROOT/'src/natural-anomaly-data.h').write_text('\n'.join(header),encoding='utf-8')
    p=ROOT/'src/rift-catalog.h'; original=(ROOT/'assets/source/natural-anomalies/legacy-catalog.h').read_text()
    original=original.replace('/* Stable system/slot taxonomy, shared by the field, scan report and archive. */','/* Legacy slots keep their identities. New taxonomy is immutable per system/slot. */\n#include "natural-anomaly-data.h"')
    original=original.replace('return (slot&1)?3:(system*17+slot*7)%3;', 'if(system<0||system>255||slot<0||slot>3)return 0;if(slot<2)return (slot&1)?3:(system*17+slot*7)%3;int t=natural_anomaly_sites[system][slot-2];return t?t:0;')
    original=original.replace('"MERIDIAN ECHO"};','"MERIDIAN ECHO",'+','.join(json.dumps(d[0]) for d in NEW)+'};')
    # Append aligned entries to each of the original four-entry arrays.
    for name,index in [('rift_reports',1),('rift_lore',2)]:
        start=original.index('static const char *'+name); end=original.index('\n };',start)
        extra=',\n'+',\n'.join(' '+json.dumps(d[index]) for d in NEW)
        original=original[:end]+extra+original[end:]
    p.write_text(original,encoding='utf-8')
    look=['/* RGB byte order matches the PSP framebuffer; immutable style parameters. */','typedef struct {unsigned ink,accent,core; float radius; unsigned char rarity;} NaturalLook;', 'static const NaturalLook natural_looks[RIFT_TYPE_COUNT]={',
          ' {0x00ffb14b,0x00e755ba,0x00fcebb9,300,0},{0x0079d9f5,0x00d4d650,0x00daf8ff,300,0},{0x00ad50ed,0x00438cfa,0x00c4e7ff,300,0},{0x00ffb878,0x00e3daba,0x00fff8e0,300,0},']
    for name,report,lore,a,b,c,size,rarity in NEW:
        rgb=lambda v:sum(n<<(8*i) for i,n in enumerate(v))
        look.append(f' {{0x{rgb(a):08x},0x{rgb(b):08x},0x{rgb(c):08x},{size},{rarity}}}, /* {name} */')
    look+=['};',''];(ROOT/'src/natural-anomaly-looks.h').write_text('\n'.join(look),encoding='utf-8')
    report={'types':[dict(id=i+4,name=d[0],rarity=['regular','unusual','rare'][d[7]],occurrences=sum(v==i+4 for row in table for v in row),regions=len({s['region'] for s,row in zip(systems,table) if i+4 in row}),radius=d[6]) for i,d in enumerate(NEW)],'systems':[dict(s,slots=table[s['system']]) for s in systems]}
    out=ROOT/'outputs/anomalies466';out.mkdir(parents=True,exist_ok=True);(out/'distribution.json').write_text(json.dumps(report,indent=2))
    print('28 new types, 384 sites, all 256 systems; legacy slots preserved.')

if __name__=='__main__':main()

